type Product struct {
    ID    int     `json:"id"`
    Name  string  `json:"name"`
    Price float64 `json:"price"`
}

var productCache []Product
var cacheInitOnce sync.Once

func initProductCache() {
    // 模拟从数据库获取所有商品，在服务启动时初始化
    for i := 1; i <= 1000; i++ {
        productCache = append(productCache, Product{ID: i, Name: fmt.Sprintf("Product %d", i), Price: float64(i * 10)})
    }
    fmt.Println("Product cache initialized at", time.Now())
}

func getRecommendedProducts(userID int) []Product {
    cacheInitOnce.Do(initProductCache)

    // 基于用户ID的简单推荐逻辑：返回用户ID相关的商品
    var recommended []Product
    for _, product := range productCache {
        if product.ID%userID == 0 { // 示例逻辑：选择ID能被用户ID整除的商品
            recommended = append(recommended, product)
            if len(recommended) >= 10 {
                break
            }
        }
    }
    return recommended
}

func recommendHandler(w http.ResponseWriter, r *http.Request) {
    userIDStr := r.URL.Query().Get("user_id")
    if userIDStr == "" {
        http.Error(w, "Missing user_id parameter", http.StatusBadRequest)
        return
    }
    userID, err := strconv.Atoi(userIDStr)
    if err != nil {
        http.Error(w, "Invalid user_id", http.StatusBadRequest)
        return
    }

    products := getRecommendedProducts(userID)

    jsonData, err := json.Marshal(products)
    if err != nil {
        http.Error(w, "Internal Server Error", http.StatusInternalServerError)
        return
    }
    w.Header().Set("Content-Type", "application/json")
    w.Write(jsonData)
}

func main() {
    http.HandleFunc("/recommend", recommendHandler)
    http.ListenAndServe(":8080", nil)
}
