async function processUserActivity(userId, dateRange) {
    try {
        // 1. 并行获取来自三个不同微服务的用户活动日志
        const results = await Promise.allSettled([
            authService.fetchLoginHistory(userId, dateRange),
            transactionService.getTransactions(userId, dateRange),
            socialService.getInteractions(userId, dateRange)
        ]);

        // 2. 处理各服务返回的结果
        const processedData = [];
        results.forEach((result, index) => {
            if (result.status === 'fulfilled') {
                const data = result.value;
                // 数据处理逻辑：转换格式并添加元数据
                switch(index) {
                    case 0: 
                        processedData.push({
                            source: 'auth',
                            events: data.logs.map(log => ({ ...log, processedAt: new Date() }))
                        });
                        break;
                    case 1:
                        processedData.push({
                            source: 'transaction',
                            events: data.transactions.filter(tx => tx.amount > 0).map(tx => ({
                                ...tx,
                                processedAt: new Date(),
                                category: 'financial'
                            }))
                        });
                        break;
                    case 2:
                        processedData.push({
                            source: 'social',
                            events: data.interactions.map(interaction => ({
                                ...interaction,
                                processedAt: new Date(),
                                engagementScore: calculateEngagement(interaction)
                            }))
                        });
                        break;
                }
            } else {
                // 记录错误但不中断流程
                console.error(`Failed to fetch data from service index ${index}:`, result.reason);
                processedData.push({ source: `unknown_${index}`, events: [], error: result.reason.message });
            }
        });

        // 3. 将所有处理后的事件按时间排序，生成统一的活动时间线
        const allEvents = processedData.flatMap(sourceData => sourceData.events);
        const sortedTimeline = allEvents.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

        // 4. 触发一个异步的后处理任务（如发送分析报告）
        setTimeout(() => {
            analyticsService.sendActivityReport({
                userId,
                eventCount: sortedTimeline.length,
                dateRange
            }).catch(e => console.error('Failed to send report:', e));
        }, 0);

        return {
            success: true,
            timeline: sortedTimeline,
            sources: processedData.map(d => d.source)
        };

    } catch (error) {
        console.error('Critical error in processUserActivity:', error);
        return { success: false, error: error.message };
    }
}

