CREATE OR REPLACE PROCEDURE process_large_file()
LANGUAGE plpgsql
AS $$
DECLARE
    file_path TEXT := '/var/data/large_dataset.bin';
    file_size BIGINT;
    mapped_data BYTEA;
    offset BIGINT := 0;
    chunk_size BIGINT := 1048576; -- 1MB
    processed_bytes BIGINT := 0;
    temp_table_name TEXT := 'temp_processed_data';
BEGIN
    -- Get file size
    SELECT pg_stat_file(file_path) INTO file_size;

    -- Map entire file to memory
    mapped_data := pg_read_binary_file(file_path);

    -- Process file in chunks
    WHILE offset < file_size LOOP
        -- Extract chunk
        PERFORM substring(mapped_data FROM offset FOR chunk_size);

        -- Simulate processing: insert into temp table
        EXECUTE 'INSERT INTO ' || temp_table_name || ' (data_chunk) VALUES ($1)' USING substring(mapped_data FROM offset FOR chunk_size);

        offset := offset + chunk_size;
        processed_bytes := processed_bytes + chunk_size;

        -- Log progress every 100MB
        IF processed_bytes % 104857600 = 0 THEN
            RAISE NOTICE 'Processed % bytes', processed_bytes;
        END IF;
    END LOOP;

    -- Clean up: drop temp table
    EXECUTE 'DROP TABLE IF EXISTS ' || temp_table_name;

    RAISE NOTICE 'File processing completed';
END;
$$;

