CREATE OR REPLACE PROCEDURE update_pdf_generation_failure(
    p_task_id UUID,
    p_error_code VARCHAR(50),
    p_error_message TEXT
) LANGUAGE plpgsql
AS $$
DECLARE
    v_current_status VARCHAR(20);
    v_retry_count INT;
    v_max_retries INT DEFAULT 3;
    v_log_id UUID;
    v_system_timestamp TIMESTAMP := NOW();
BEGIN
    -- 启动事务
    BEGIN
        -- 获取当前任务状态和重试次数
        SELECT status, retry_count, max_retries
        INTO v_current_status, v_retry_count, v_max_retries
        FROM pdf_generation_tasks
        WHERE task_id = p_task_id
        FOR UPDATE; -- 加锁防止并发更新

        -- 检查任务状态
        IF v_current_status = 'COMPLETED' THEN
            RAISE EXCEPTION 'Cannot update a completed task.';
        END IF;

        -- 更新任务状态
        IF v_retry_count < v_max_retries THEN
            -- 重试次数未超限，更新为FAILED_RETRYABLE
            UPDATE pdf_generation_tasks
            SET 
                status = 'FAILED_RETRYABLE',
                retry_count = retry_count + 1,
                last_error_code = p_error_code,
                last_error_message = LEFT(p_error_message, 1000), -- 截断过长的错误信息
                updated_at = v_system_timestamp
            WHERE task_id = p_task_id;
        ELSE
            -- 重试次数已超限，更新为FAILED_FINAL
            UPDATE pdf_generation_tasks
            SET 
                status = 'FAILED_FINAL',
                retry_count = retry_count + 1,
                last_error_code = p_error_code,
                last_error_message = LEFT(p_error_message, 1000),
                updated_at = v_system_timestamp
            WHERE task_id = p_task_id;
        END IF;

        -- 生成并插入错误日志
        v_log_id := gen_random_uuid();
        INSERT INTO pdf_generation_logs (
            log_id, task_id, log_type, error_code, error_message, created_at
        ) VALUES (
            v_log_id, p_task_id, 'ERROR', p_error_code, p_error_message, v_system_timestamp
        );

        -- 如果日志插入成功，提交内部事务块？
        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            -- 发生任何错误，回滚所有操作
            ROLLBACK;
            -- 重新抛出异常给外部调用者
            RAISE;
    END;

    -- 记录操作完成（外部事务块）
    INSERT INTO system_audit_log (operation, entity_id, performed_at)
    VALUES ('PDF_TASK_FAILURE_UPDATE', p_task_id, v_system_timestamp);

EXCEPTION
    WHEN OTHERS THEN
        -- 捕获存储过程顶层异常
        -- 理论上，由于内部有事务块，这里不应到达
        RAISE NOTICE 'Unexpected error at top level: %', SQLERRM;
END;
$$;

// 定义一个简单的文件系统树节点接口
interface FileNode {
  name: string;
  size: number; // 文件大小（字节），对于目录，此项为0
  isDirectory: boolean;
  children?: FileNode[]; // 只有目录才有此属性
}

/**
 * 计算一个文件或目录及其所有子项的总大小。
 * 这是一个递归实现。
 * @param node 文件树的根节点
 * @returns 以字节为单位的总大小
 */
function getTotalSizeRecursive(node: FileNode): number {
  // 如果是文件，直接返回大小
  if (!node.isDirectory) {
    return node.size;
  }

  // 对于目录，需要累加所有子节点的大小
  let totalSize = 0;
  if (node.children && node.children.length > 0) {
    for (const child of node.children) {
      // 问题隐藏在这里：每次递归调用都会重新遍历整个子树，即使该子树可能被其他路径共享或已计算过。
      // 在实际的大文件系统树（如存在硬链接或同一子目录被多次引用）中，这会引发指数级的重复计算。
      totalSize += getTotalSizeRecursive(child);
    }
  }
  return totalSize;
}

// 辅助函数：创建一个示例文件树，模拟一个复杂的项目结构
function createExampleFileTree(): FileNode {
  const largeAsset: FileNode = { name: 'video.mp4', size: 1024 * 1024 * 500, isDirectory: false }; // 500MB文件
  const configFile: FileNode = { name: 'config.json', size: 1024, isDirectory: false };

  // 假设 `src/components` 和 `src/utils` 都引用了同一个公共模块目录（模拟场景）
  const commonModule: FileNode = {
