    size: 0,
    isDirectory: true,
    children: [
      { name: 'constants.ts', size: 2048, isDirectory: false },
      { name: 'helpers.ts', size: 4096, isDirectory: false },
      largeAsset, // 大型文件被放置在公共目录中
    ]
  };

  const srcComponents: FileNode = {
    name: 'components',
    size: 0,
    isDirectory: true,
    children: [
      { name: 'Button.tsx', size: 5120, isDirectory: false },
      commonModule, // 引用公共模块
    ]
  };

  const srcUtils: FileNode = {
    name: 'utils',
