import express, { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { getUserById } from '../models/user';

interface UserPayload {
  userId: string;
  iat: number;
}

export const validateAuthToken = async (req: Request, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: '未提供认证令牌' });
  }

  const token = authHeader.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: '令牌格式错误' });
  }

  // 关键修复：使用 Buffer 形式的密钥，并显式指定算法，杜绝算法混淆
  const secretString = process.env.JWT_SECRET;
  if (!secretString || secretString.trim() === '') {
    // 生产环境必须有强密钥，不应有默认值
    console.error('FATAL: JWT_SECRET is not set or is empty.');
    return res.status(500).json({ error: '服务器配置错误' });
  }
  // 假设密钥在环境变量中以 Base64 形式存储，增强安全性并避免字符串混淆
  const secretBuffer = Buffer.from(secretString, 'base64');
  if (secretBuffer.length < 32) { // 示例：简单长度检查
    console.error('FATAL: JWT_SECRET is too weak.');
    return res.status(500).json({ error: '服务器配置错误' });
  }

  let decodedPayload: UserPayload;
  try {
    // 使用 Buffer 密钥，并强制算法为 HS256
    const decoded = jwt.verify(token, secretBuffer, { algorithms: ['HS256'] }) as UserPayload;
    decodedPayload = decoded;
  } catch (err: any) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: '令牌已过期' });
    }
    // 记录详细的验证失败日志（生产环境需接入日志系统）
    console.warn(`JWT verification failed: ${err.name}`, { tokenPrefix: token.substring(0, 20) });
    return res.status(401).json({ error: '无效的认证令牌' });
  }

  try {
    const user = await getUserById(decodedPayload.userId);
    if (!user) {
      return res.status(401).json({ error: '用户不存在' });
    }
    if (!user.isActive) {
      return res.status(403).json({ error: '用户账户已被禁用' });
    }
    (req as any).user = user;
    next();
  } catch (dbError) {
    console.error('Database error during token validation:', dbError);
    return res.status(503).json({ error: '服务暂时不可用' });
  }
};
```

### 最佳实践
1.  **密钥管理**：用于 HMAC 签名（如 HS256）的密钥应具备足够的熵（长度），建议以 Base64 编码形式存储在环境变量中，并在使用时转换为 Buffer，避免作为纯文本字符串被误解析。生产环境绝对禁止使用硬编码的默认密钥。
2.  **明确的算法白名单**：在验证 JWT 时，始终使用 `algorithms` 选项明确指定你期望并支持的算法列表（如 `['HS256']`）。这是防范算法混淆攻击的第一道防线。
3.  **安全编码与日志**：移除代码中任何用于开发的默认密钥。在关键的安全验证失败处（如 JWT 验证失败、用户查找失败）添加结构化的警告或错误日志，以便于监控和审计攻击尝试，但要注意避免在日志中记录完整的敏感令牌或密钥。

